MOD = 998244353

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    a = [[0] * n for _ in range(n)]
    index = 1
    for i in range(n):
        for j in range(n):
            a[i][j] = int(data[index])
            index += 1

    # Calculate the MST weight
    mst_weight = 0
    edges = []
    for i in range(n):
        for j in range(i + 1, n):
            edges.append((a[i][j], i, j))
    edges.sort()

    parent = list(range(n))
    rank = [0] * n

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        xroot = find(x)
        yroot = find(y)
        if rank[xroot] < rank[yroot]:
            parent[xroot] = yroot
        elif rank[xroot] > rank[yroot]:
            parent[yroot] = xroot
        else:
            parent[yroot] = xroot
            rank[xroot] += 1

    for weight, u, v in edges:
        if find(u) != find(v):
            mst_weight += weight
            union(u, v)

    # Calculate the number of ways to partition the graph into k groups
    dp = [[0] * (n + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    for i in range(n):
        for k in range(i, -1, -1):
            for j in range(n):
                dp[i + 1][k + 1] = (dp[i + 1][k + 1] + dp[i][k]) % MOD

    result = [0] * (n + 1)
    for k in range(1, n + 1):
        result[k] = dp[n][k]

    print(' '.join(map(str, result[1:])))

if __name__ == "__main__":
    main()
